default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('DoHPolicy', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]$ODV_doh_policy)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient [DoHPolicy]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

---

{{ if .Vars.win11cis_level_1 }}
  {{ if .Vars.win11cis_rule_18_6_4_1 }}
registry:
  HKLM\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient\DoHPolicy:
    title: "18.6.4.1 | Ensure 'Configure DNS over HTTPS (DoH) name resolution' is set to 'Enabled: Allow DoH' or higher | DoHPolicy"
    exists: true
    value: {{ .Vars.win11cis_doh_policy }}
    type: REG_DWORD
    meta:
      workstation: 1
      CIS_ID:
        - 18.6.4.1
  {{ end }}
{{ end }}

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient')) {
    New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient' -Name 'DoHPolicy' -Value $ODV_doh_policy -PropertyType DWord -Force | Out-Null
exit 0
